import ast

# Parse the code
tree = ast.parse(code)

# Count while loops
while_loops = []
for node in ast.walk(tree):
    if isinstance(node, ast.While):
        while_loops.append(node)

assert len(while_loops) == 3, f'Should have exactly 3 while loops, found {len(while_loops)}'

# Check each while loop modifies its condition variable
modification_found = [False, False, False]
for i, while_node in enumerate(while_loops):
    for child in ast.walk(while_node):
        # Check for augmented assignments (+=, -=)
        if isinstance(child, ast.AugAssign):
            modification_found[i] = True
            break
        # Check for regular assignments to variables
        elif isinstance(child, ast.Assign):
            if isinstance(child.targets[0], ast.Name):
                var_name = child.targets[0].id
                # Check if this variable appears in while condition
                for condition_child in ast.walk(while_node.test):
                    if isinstance(condition_child, ast.Name) and condition_child.id == var_name:
                        modification_found[i] = True
                        break

assert all(modification_found), 'Each while loop should modify the variable used in its condition'

print('TEST_PASSED: Correct while loop structure')
